  "claims": [
    {
      "id": "rc:3396163565",
      "kind": "correctness",
      "harm": "IPC Cap'n Proto serialization only overwrote a local copy, failing to write CAmount values into the message and resulting in zeroed output.",
      "quote": "Current code gets a local copy, overrides the local copy and local copy gets destroyed at the end of the function. Nothing is written back to the Cap'n Proto message.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:3398153775"
      ],
      "fix_pushed": true,
      "settled_by_id": "rc:3401837725",
      "settled_by_quote": "yeah test was for proving the bug not the intention to add it so i'm glad you altered it somewhat !"
    },
    {
      "id": "c:4740188131",
      "kind": "approach",
      "harm": "Restricting construction to literals and forbidding direct integer comparison causes friction and hinders migration across the codebase.",
      "quote": "However, to be constructible only from `_sats` literals, and to be comparable only against other `CAmount` seems a bit of an overkill to me, and it hinders introduction (large change).",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "c:4741612688"
      ],
      "fix_pushed": true,
      "settled_by_id": "c:4741612688",
      "settled_by_quote": "I briefly experimented with having an operator int64_t() method and allowing comparisons against integers. What I ran into a lot was that the compiler couldn't resolve the resulting ambiguities."
    },
    {
      "id": "c:4765530904",
      "kind": "interface",
      "harm": "User-defined literals for amount units have known pitfalls and deviate from emerging C++ quantity standards that prefer unit multiplication syntax.",
      "quote": "Which is absolutely true and convinces me to vote against a `_sat` UDL.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "c:4809818861"
      ],
      "fix_pushed": true,
      "settled_by_id": "c:5407105124",
      "settled_by_quote": "Latest push removes the `_sats` UDL. Instead the commits get by on `CAmount{<literal>}` until the end, when a `sats` unit is defined and applied as `<literal>*sats`."
    },
    {
      "id": "rc:3494097004",
      "kind": "interface",
      "harm": "Placing CAmount serialization outside the class in serialize.h breaks type encapsulation.",
      "quote": "Could we rather encapsulate the serialization inside the new type?",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:3505561954"
      ],
      "fix_pushed": true,
      "settled_by_id": "rc:3505561954",
      "settled_by_quote": "Agreed, thanks for pushing back on this. (Edit: Fixed in later push)."
    },
    {
      "id": "r:4475868693",
      "kind": "scope",
      "harm": "Transitioning the entire codebase to the new CAmount class in a single monolithic PR is too risky and onerous to review compared to an incremental rollout.",
      "quote": "As mentioned by others, I am also not comfortable with taking such a large change in one step. I would prefer introducing a new amount type first, with a few focused examples, and then converting call sites gradually.",
      "blocking": true,
      "status": "open",
      "author_replies": [
        "r:4599764409"
      ],
      "fix_pushed": false,
      "settled_by_id": "",
      "settled_by_quote": ""
    }
  ],
  "support": [
    {
      "id": "c:4679584491",
      "verdict": "Concept ACK",
      "reason": "",
      "substantive": false
    },
    {
      "id": "c:4712614640",
      "verdict": "Concept ACK",
      "reason": "New CAmount implementation seems simple and clean and adds safety benefits.",
      "substantive": true
    }
  ],
  "notes": "Initial record for the PR. l0rinc filed a Changes Requested review objecting to replacing CAmount everywhere in one massive PR rather than introducing the class incrementally; this remains open. Objections regarding IPC serialization, type encapsulation in serialize.h, and the proposed _sats literal were resolved."
